#[derive(Serialize, Deserialize)]
#[serde(default)]
pub(crate) struct GraphTile {
    #[serde(skip)]
    tiles: Option<HttpTiles>,
    #[serde(skip)]
    trip_icon: Option<TextureHandle>,
    map_memory: MapMemory,
    is_autonavi: bool,
}

impl Default for GraphTile {
    fn default() -> Self {
        Self {
            tiles: None,
            trip_icon: None,
            map_memory: MapMemory::default(),
            is_autonavi: false,
        }
    }
}

impl PartialEq for GraphTile {
    fn eq(&self, _: &Self) -> bool {
        true
    }
}

impl Tile for GraphTile {
    const NAME: &'static str = "Graph";
    fn main_display(&mut self, app: &mut App, ui: &mut Ui) {
        puffin::profile_function!();
        ui.horizontal(|ui| {
            if ui.button("Auto layout").clicked() {
                auto_layout(app);
            }
            if ui.checkbox(&mut self.is_autonavi, "使用高德地图").changed() || self.tiles.is_none()
            {
                let ctx = ui.ctx().clone();
                self.tiles = Some(if self.is_autonavi {
                    HttpTiles::new(AutoNavi, ctx)
                } else {
                    HttpTiles::new(OpenStreetMap, ctx)
                });
            }
        });
        Frame::canvas(ui.style())
            .inner_margin(Margin::ZERO)
            .outer_margin(Margin::ZERO)
            .stroke(Stroke::NONE)
            .show(ui, |ui| {
                main_display(self, app, ui);
            });
    }
}

const ICON_HALF_SIZE: f32 = 18.0;

struct MapPlugin<'a> {
    app: &'a mut App,
    trip_icon: TextureId,
}

impl<'a> walkers::Plugin for MapPlugin<'a> {
    fn run(
        self: Box<Self>,
        ui: &mut Ui,
        response: &Response,
        projector: &walkers::Projector,
        _map_memory: &MapMemory,
    ) {
        puffin::profile_function!();

        let pos_to_lon_lat = |pos: Pos2| -> LonLat {
            let coor = projector.unproject(pos.to_vec2());
            Wgs84LonLat {
                lon: coor.x(),
                lat: coor.y(),
            }
            .into()
        };

        let lon_lat_to_pos = |coor: LonLat| {
            let wgs84_lon_lat: Wgs84LonLat = coor.into();
            projector.project(lon_lat(wgs84_lon_lat.lon, wgs84_lon_lat.lat)).to_pos2()
        };

        let coor_min = pos_to_lon_lat(response.rect.left_top());
        let coor_max = pos_to_lon_lat(response.rect.right_bottom());

        let interact_pos = if response.clicked()
            && let Some(pos) = response.interact_pointer_pos()
            && !matches!(self.app.selected_items, SelectedItems::Nodes(_))
            && matches!(self.app.selected_items.take(), SelectedItems::None)
        {
            Some(pos)
        } else {
            None
        };

        const SELECTION_THRESHOLD_SQUARE: f32 = ICON_HALF_SIZE * ICON_HALF_SIZE;

        let mut callback = gpu_draw::GraphCallback::new();
        callback.populate_uniforms(response.rect);

        let App {
            source,
            timer,
            selected_items,
            ..
        } = self.app;

        let mut trip_leg_text = Vec::new();
        let mut node_text = Vec::new();

        let draw_world = source.world.clone();

        if let SelectedItems::Nodes(nodes) = &selected_items
            && nodes.len() == 1
            && let node_key = nodes.first()
            && let Some(node) = source.graph.nodes().get(node_key)
            && let Some(pointer_pos) = ui.pointer_hover_pos()
        {
            let match_rect = Rect::from_pos(pointer_pos).expand(30.0);
            let matched_station = source
                .spatial()
                .nodes
                .get(
                    pos_to_lon_lat(match_rect.left_top()),
                    pos_to_lon_lat(match_rect.right_bottom()),
                )
                .next();
            let dt = ui.input(|input| input.stable_dt).at_most(0.1);
            let mut requires_repaint = false;
            let new_pos =
                matched_station.map_or(pointer_pos, |matched| lon_lat_to_pos(matched.coor));
            let smoothed_pos = ui.data_mut(|data| {
                let smoothed: &mut Pos2 =
                    data.get_temp_mut_or(ui.scope_id().with("pointer animation"), new_pos);
                let t = emath::exponential_smooth_factor(0.9, 0.05, dt);
                *smoothed = smoothed.lerp(new_pos, t);
                if smoothed.distance_sq(new_pos) < 0.5 {
                    requires_repaint = true;
                }
                *smoothed
            });
            if requires_repaint {
                ui.request_repaint();
            }
            ui.painter().line_segment(
                [lon_lat_to_pos(node.pos), smoothed_pos],
                Stroke::new(1.0, Color32::RED),
            );
            ui.painter().circle(
                smoothed_pos,
                6.0,
                Color32::RED.gamma_multiply(0.8),
                Stroke::new(1.0, Color32::RED),
            );
            if response.clicked()
                && let Some(matched) = matched_station
            {
                let _ = source.mutate(|mut world| {
                    world.graph.connect_nodes((*node_key, matched.node_key));
                    Ok(world)
                });
            } else if response.secondary_clicked() {
                *selected_items = SelectedItems::None;
            }
        }

        {
            puffin::profile_scope!("map_trip_legs");
            for leg in source.spatial().trip_legs.get(
                coor_min,
                coor_max,
                TimetableTime(timer.seconds() as i32),
            ) {
                let Some(trip) = draw_world.trips.get(&leg.trip_key) else {
                    continue;
                };
                let fill = trip
                    .service_class
                    .and_then(|key| source.service_classes.get(&key))
                    .map_or(Color32::GRAY, |wfc| wfc.style.color);
                let Some(&[a, b]) = leg.interval.first_chunk() else {
                    continue;
                };
                let (first, next) = if leg.is_hi_to_lo { (a, b) } else { (b, a) };
                let pos1 = lon_lat_to_pos(first);
                let pos2 = lon_lat_to_pos(next);
                let progress = {
                    let t1 = leg.curr_dep.0 as f64;
                    let t2 = leg.next_arr.0 as f64;
                    let t_current = timer.seconds();
                    // curr arr time is simply out of range. so just clamp the value...
                    inverse_lerp(t1..=t2, t_current).unwrap_or(0.0).at_least(0.0) as f32
                };
                // t_current is a float while t2 is a i32
                // this leaves a ~1 in-app second gap that duplicates entries.
                // simply remove the entry when progress > 1.0.
                if progress > 1.0 {
                    continue;
                }
                let trip_pos = pos1.lerp(pos2, progress);
                trip_leg_text.push((
                    trip_pos,
                    trip.name.as_str(),
                    fill,
                    matches!(
                        selected_items,
                        SelectedItems::Trips(selected_trips) if selected_trips.contains(&leg.trip_key.into())
                    ),
                ));
                if let Some(interact_pos) = interact_pos
                    && (interact_pos - trip_pos).length_sq() <= SELECTION_THRESHOLD_SQUARE
                {
                    selected_items.replace(SelectedItem::Trip(leg.trip_key.into()))
                }
            }
        }

        {
            puffin::profile_scope!("map_nodes");
            callback.node_points.clear();
            for node in source.spatial().nodes.get(coor_min, coor_max) {
                let pos = lon_lat_to_pos(node.coor);
                callback.node_points.push(graph_nodes::graph_nodes::NodePoint {
                    screen_pos: (pos - response.rect.min).into(),
                });
                node_text.push((
                    pos,
                    node.node_key,
                    draw_world
                        .graph
                        .nodes()
                        .get(&node.node_key)
                        .map_or("<UNKNOWN>", |wfc| &wfc.name),
                ));
            }
        }

        {
            puffin::profile_scope!("map_intervals");
            callback.interval_points.clear();
            for interval in source.spatial().intervals.get(coor_min, coor_max) {
                let last = interval.nodes.len().saturating_sub(1);
                callback.interval_points.extend(interval.nodes.iter().enumerate().map(
                    |(idx, &node)| {
                        graph_intervals::graph_intervals::IntervalPoint::new(
                            {
                                let pos = lon_lat_to_pos(node) - response.rect.left_top();
                                [pos.x, pos.y]
                            },
                            u32::from(idx != last),
                        )
                    },
                ));
            }
        }

        ui.painter().add(callback.paint_callback(response.rect));

        {
            puffin::profile_scope!("map_text");
            for &(pos, node_key, text) in &node_text {
                ui.painter().text(
                    pos + Vec2::new(8.0, 0.0),
                    Align2::LEFT_CENTER,
                    text,
                    FontId::proportional(13.0),
                    ui.visuals().text_color(),
                );
                if response.clicked()
                    && let Some(pointer_pos) = ui.pointer_hover_pos()
                    && pointer_pos.distance_sq(pos) <= SELECTION_THRESHOLD_SQUARE
                {
                    selected_items.replace(SelectedItem::Node(node_key))
                }
            }

            for (pos, text, fill, is_selected) in trip_leg_text {
                ui.painter().image(
                    self.trip_icon,
                    Rect::from_center_size(pos, Vec2::splat(ICON_HALF_SIZE * 2.0)),
                    Rect::from_min_max(pos2(0.0, 0.0), pos2(1.0, 1.0)),
                    Color32::WHITE,
                );
                ui.painter().text(
                    pos + Vec2::new(0.0, -ICON_HALF_SIZE),
                    Align2::CENTER_BOTTOM,
                    text,
                    FontId::proportional(13.0),
                    fill,
                );
                if is_selected {
                    ui.painter().circle(
                        pos,
                        ICON_HALF_SIZE + 6.0,
                        Color32::RED.gamma_multiply(0.5),
                        Stroke::new(1.0, Color32::RED),
                    );
                }
            }
        }
    }
}

// TODO: remove this
fn auto_layout(app: &mut App) {
    puffin::profile_function!();
    let mut graph: ForceGraph<NodeKey, ()> = ForceGraph::default();
    let mut idx_map = HashMap::with_capacity(app.source.graph.nodes().len());
    for &node in app.source.graph.nodes().keys() {
        let idx = graph.add_node(Node::new("", node));
        idx_map.insert(node, idx);
    }
    for edge_key in app.source.graph.intervals().keys() {
        graph.add_edge(
            idx_map.get(&edge_key.hi).copied().unwrap(),
            idx_map.get(&edge_key.lo).copied().unwrap(),
            (),
        );
    }
    let mut simulation = Simulation::from_graph(graph, SimulationParameters::default());
    for _ in 0..1000 {
        simulation.update(0.1);
        let max_step = simulation
            .get_graph()
            .node_weights()
            .map(|node| node.location.distance(node.old_location))
            .fold(0.0_f32, f32::max);
        if max_step < 0.1 {
            break;
        }
    }
    let _ = app.source.mutate(|mut world| {
        for node in simulation.get_graph().node_weights() {
            let new_coor: Wgs84LonLat = XyPos {
                x: node.location.x as f64,
                y: node.location.y as f64,
            }
            .into();
            world.graph.update_node_coordinate(node.data, new_coor.into());
        }
        Ok(world)
    });
}

fn main_display(tile: &mut GraphTile, app: &mut App, ui: &mut Ui) {
    puffin::profile_function!();
    let trip_icon = tile.trip_icon.get_or_insert_with(|| load_trip_icon(ui.ctx())).id();
    let map = Map::new(
        match tile.tiles.as_mut() {
            // map::new wants dyn, thus rebind
            Some(tiles) => Some(tiles),
            None => None,
        },
        &mut tile.map_memory,
        lon_lat(0.0, 0.0),
    )
    .with_projection(if tile.is_autonavi {
        &MercatorProjectionGcj02
    } else {
        &MercatorProjection
    })
    .with_plugin(MapPlugin { app, trip_icon });
    ui.add(map);
}

/// Decodes the embedded trip icon and uploads it as an egui texture. Every trip uses the same
/// texture, so egui batches all icon quads into one draw call.
fn load_trip_icon(ctx: &egui::Context) -> TextureHandle {
    let decoded = image::load_from_memory(include_bytes!("../../assets/raicho_485.png"))
        .expect("the embedded trip icon must be a valid PNG")
        .into_rgba8();

    // The icon is drawn from one square quad, so pad it with transparent pixels instead of
    // stretching it. This preserves the original aspect ratio.
    let side = decoded.width().max(decoded.height());
    let mut rgba = image::RgbaImage::new(side, side);
    let x = i64::from((side - decoded.width()) / 2);
    let y = i64::from((side - decoded.height()) / 2);
    image::imageops::overlay(&mut rgba, &decoded, x, y);

    let image = ColorImage::from_rgba_unmultiplied([side as usize, side as usize], rgba.as_raw());
    ctx.load_texture("graph_trip_icon", image, TextureOptions::LINEAR)
}
